def swap_random_letters(table):
    rows, cols = len(table), len(table[0])
    pos1 = (random.randint(0, rows - 1), random.randint(0, cols - 1))
    pos2 = (random.randint(0, rows - 1), random.randint(0, cols - 1))
    
    while pos1 == pos2:
        pos2 = (random.randint(0, rows - 1), random.randint(0, cols - 1))
    row1, col1 = pos1
    row2, col2 = pos2
    table[row1][col1], table[row2][col2] = table[row2][col2], table[row1][col1]
    
    return table
